"""json2csv.py — Convert JSON array from stdin to CSV on stdout.

Usage:
    cat data.json | python json2csv.py
    python json2csv.py < data.json

Only Python stdlib is used.
"""
import json
import sys


def escape_csv(value: str) -> str:
    """Escape a value for CSV output."""
    if not value:
        return value
    if ',' in value or '"' in value or '\n' in value or '\r' in value:
        value = value.replace('"', '""')
        return f'"{value}"'
    return value


def main() -> None:
    try:
        data = json.load(sys.stdin)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON — {e}", file=sys.stderr)
        sys.exit(1)

    if not isinstance(data, list):
        print("Error: Input must be a JSON array", file=sys.stderr)
        sys.exit(1)

    if not data:
        # Empty array — output nothing (empty CSV)
        return

    # Collect all keys across all objects, preserving insertion order
    keys: list[str] = []
    seen: set[str] = set()
    for obj in data:
        if not isinstance(obj, dict):
            continue
        for k in obj:
            if k not in seen:
                seen.add(k)
                keys.append(k)

    if not keys:
        return

    # Print header
    header = ','.join(escape_csv(k) for k in keys)
    print(header)

    # Print rows
    for obj in data:
        if not isinstance(obj, dict):
            row = ','.join('' for _ in keys)
            print(row)
            continue
        row_values: list[str] = []
        for k in keys:
            val = obj.get(k)
            if val is None:
                row_values.append('')
            elif isinstance(val, bool):
                row_values.append('true' if val else 'false')
            elif isinstance(val, (int, float)):
                row_values.append(str(val))
            else:
                row_values.append(escape_csv(str(val)))
        print(','.join(row_values))


if __name__ == '__main__':
    main()
"}

